@layer theme, base, components, utilities;

@layer components {
  .root {
    --checkbox-size: 16px;
    --ui-icon-stroke: var(--ui-icon-stroke-medium);

    position: relative;
    display: inline-flex;
    align-items: baseline;
    gap: var(--ui-space-2);
    max-width: 100%;
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
  }

  /* Empty, so its baseline is its bottom edge; shifting by half its height less
     0.5cap centers it on the first line's capitals. The margin cancels the shift. */
  .control {
    --optical: calc(var(--checkbox-size) / 2 - 0.5cap);
    position: relative;
    flex-shrink: 0;
    width: var(--checkbox-size);
    height: var(--checkbox-size);
    margin-top: calc(var(--optical) * -1);
    translate: 0 var(--optical);
  }

  /* Without the `cap` unit (Safari before 17.2) --optical is invalid and the
     control drops onto the baseline, 2-6px high. The system faces' capitals
     are about 0.7em tall, so half of that stands in. */
  @supports not (height: 1cap) {
    .control {
      --optical: calc(var(--checkbox-size) / 2 - 0.35em);
    }
  }

  .control:only-child {
    margin-top: 0;
    translate: none;
  }

  .box {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: calc(var(--ui-radius-sm) / 2);
    appearance: none;
    background: var(--ui-surface);
    /* The one edge every box and control has; hover steps it darker. */
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border-strong);
    color: var(--ui-foreground);
    cursor: inherit;
    /* Unchecking: the fill waits for the mark to un-draw. Hover must not change
       background here or it cancels that delay. */
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color) var(--ui-dur-instant),
      box-shadow var(--ui-dur-instant) var(--ui-ease-color);
  }

  .root:is([data-state="on"], [data-state="mixed"]) .box {
    background: var(--ui-accent);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-accent);
    color: var(--ui-on-accent);
    transition-delay: 0s;
  }

  .mark {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    overflow: visible;
    fill: none;
    stroke: var(--ui-on-accent);
    stroke-width: var(--ui-icon-stroke, 1.5);
    stroke-linecap: round;
    stroke-linejoin: round;
    pointer-events: none;
  }

  /* pathLength="1": 0 is drawn, 1.05 is hidden with no round-cap dot left. */
  .mark path {
    d: path("M4.25 8.25L6.75 10.75L11.75 5.25");
    stroke-dasharray: 1 2;
    stroke-dashoffset: 1.05;
    transition: stroke-dashoffset var(--ui-dur-instant) var(--ui-ease-exit);
  }

  .root[data-shape="dash"] .mark path {
    d: path("M4.75 8L6.75 8L11.25 8");
  }

  .root:is([data-state="on"], [data-state="mixed"]) .mark path {
    stroke-dashoffset: 0;
    transition: stroke-dashoffset var(--ui-dur-base) var(--ui-ease-draw);
  }

  .root[data-morph] .mark path {
    transition:
      stroke-dashoffset var(--ui-dur-base) var(--ui-ease-draw),
      d var(--ui-dur-snap) var(--ui-ease-snap);
  }

  @media (hover: hover) {
    .root:hover:not([data-disabled]) .box {
      box-shadow:
        inset 0 0 0 var(--ui-hairline) var(--ui-muted);
    }
    .root:is([data-state="on"], [data-state="mixed"]):hover:not([data-disabled]) .box {
      background: color-mix(in oklch, var(--ui-accent) 86%, var(--ui-on-accent));
    }
  }

  .root:active:not([data-disabled]) .box {
    background: var(--ui-fill-strong-solid);
    transition-duration: var(--ui-dur-press);
    transition-delay: 0s;
  }

  .root:is([data-state="on"], [data-state="mixed"]):active:not([data-disabled]) .box {
    background: color-mix(in oklch, var(--ui-accent) 78%, var(--ui-on-accent));
  }

  .box:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .text {
    display: grid;
    gap: var(--ui-space-1);
    min-width: 0;
  }

  .label {
    font-weight: var(--ui-weight-medium);
  }

  .description {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
    letter-spacing: 0;
    text-wrap: pretty;
  }

  .root[data-disabled] {
    cursor: default;
  }

  .root[data-disabled] :is(.control, .label) {
    opacity: 0.5;
  }

  .control::after {
    content: "";
    position: absolute;
    inset: calc((var(--checkbox-size) - 24px) / 2);
  }

  @media (pointer: coarse) {
    .control::after {
      inset: calc((var(--checkbox-size) - 40px) / 2);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .mark path,
    .root:is([data-state="on"], [data-state="mixed"]) .mark path,
    .root[data-morph] .mark path {
      transition: none;
    }
  }
}

"use client";

import { useId, useState, type CSSProperties, type ReactNode, type Ref } from "react";
import { Checkbox as BaseCheckbox } from "@base-ui/react/checkbox";
import styles from "./checkbox.module.css";

// Same commands so CSS can morph `d`; keep in sync with the stylesheet.
const CHECK = "M4.25 8.25L6.75 10.75L11.75 5.25";
const DASH = "M4.75 8L6.75 8L11.25 8";

type State = "off" | "on" | "mixed";

type CheckboxProps = Omit<
  BaseCheckbox.Root.Props,
  "className" | "style" | "render" | "nativeButton" | "inputRef" | "onCheckedChange" | "ref"
> & {
  className?: string;
  style?: CSSProperties;
  label?: ReactNode;
  description?: ReactNode;
  /** Shows a dash and reads as "mixed"; clicking calls `onCheckedChange(true)`. */
  indeterminate?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  /** The hidden form `<input>` Base UI renders beside the box. */
  ref?: Ref<HTMLInputElement>;
};

export function Checkbox({
  label,
  description,
  indeterminate = false,
  checked: controlledChecked,
  defaultChecked = false,
  onCheckedChange,
  className,
  id,
  disabled,
  ref,
  ...props
}: CheckboxProps) {
  const fallbackId = useId();
  const controlId = id ?? fallbackId;
  const labelId = `${controlId}-label`;
  const descriptionId = `${controlId}-description`;

  const [uncontrolledChecked, setUncontrolledChecked] = useState(defaultChecked);
  const checked = controlledChecked ?? uncontrolledChecked;
  const state: State = indeterminate ? "mixed" : checked ? "on" : "off";

  // Keep the last shape while hidden so it un-draws as itself.
  const [shown, setShown] = useState(state);
  const [shape, setShape] = useState<"check" | "dash">(state === "mixed" ? "dash" : "check");
  const [morph, setMorph] = useState(false);
  if (shown !== state) {
    setShown(state);
    setMorph(shown !== "off" && state !== "off");
    if (state !== "off") setShape(state === "mixed" ? "dash" : "check");
  }

  return (
    <label
      className={className ? `${styles.root} ${className}` : styles.root}
      data-state={state}
      data-shape={shape}
      data-morph={morph || undefined}
      data-disabled={disabled || undefined}
    >
      <span className={styles.control}>
        <BaseCheckbox.Root
          // A native button, so the wrapping label and `id` land on the control itself.
          nativeButton
          render={<button type="button" />}
          id={controlId}
          inputRef={ref}
          className={styles.box}
          checked={checked}
          indeterminate={indeterminate}
          disabled={disabled}
          aria-labelledby={label ? labelId : undefined}
          aria-describedby={description ? descriptionId : undefined}
          onCheckedChange={(next) => {
            if (controlledChecked === undefined) setUncontrolledChecked(next);
            onCheckedChange?.(next);
          }}
          {...props}
        />
        <svg className={styles.mark} viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
          {/* Fallback for browsers without CSS `d`. */}
          <path d={shape === "dash" ? DASH : CHECK} pathLength={1} />
        </svg>
      </span>
      {(label || description) && (
        <span className={styles.text}>
          {label && (
            <span id={labelId} className={styles.label}>
              {label}
            </span>
          )}
          {description && (
            <span id={descriptionId} className={styles.description}>
              {description}
            </span>
          )}
        </span>
      )}
    </label>
  );
}

@layer theme, base, components, utilities;

/* Shared text utilities; other components compose these classes. */

/* The fade only shows when text overflows: otherwise the scroll timeline is inactive. */

@property --truncate-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  /* Text that's never cut: a long name, email or path breaks onto the next
     line, inside a word only when there's nowhere else to break. Use this for
     anything a person needs to read in full. */
  .wrap {
    min-width: 0;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  /* One line, fading at the end when cut. Only for rows that must keep a
     fixed height (a virtualized table); give the full text a title too. The padding/negative margin stops
     overflow: hidden clipping descenders and accents at tight line heights. */
  .truncate {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    padding-block: 0.2em;
    margin-block: -0.2em;
  }

  /* Several lines; set --truncate-lines (default 2). */
  .truncateLines {
    overflow: hidden;
    max-height: calc(var(--truncate-lines, 2) * 1lh);
  }

  @supports (animation-timeline: scroll()) {
    .truncate,
    .truncateLines {
      --truncate-to: right;
      animation: truncate-overflow linear both;
    }

    :is([dir="rtl"]) .truncate,
    :is([dir="rtl"]) .truncateLines {
      --truncate-to: left;
    }

    .truncate {
      mask-image: linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      animation-timeline: scroll(self inline);
    }

    .truncateLines {
      mask-image:
        linear-gradient(#000 0 0),
        linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      mask-size: 100% calc(100% - 1lh), 100% 1lh;
      mask-position: top, bottom;
      mask-repeat: no-repeat;
      animation-timeline: scroll(self block);
    }
  }

  /* Without scroll timelines, fall back to an ellipsis. */
  @supports not (animation-timeline: scroll()) {
    .truncate {
      text-overflow: ellipsis;
    }

    .truncateLines {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--truncate-lines, 2);
    }
  }

  @keyframes truncate-overflow {
    from,
    to {
      --truncate-fade: 24px;
    }
  }

  /* Visually hidden, still read by screen readers. */
  .srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* Work in progress: a light band sweeps across dimmed text. --sweep-dim sets the dim. */
  .sweep {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation: sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sweep {
      mask-image: none;
      animation: none;
    }
  }
}

@layer theme, base, components, utilities;

/* The real label, for screen readers and find-in-page. */
.label {
  composes: srOnly from "../text/text.module.css";
}

/* Block padding keeps descenders inside the mask. */
@property --morph-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  .root {
    position: relative;
    display: inline-flex;
    white-space: pre;
  }

  .row {
    --morph-to: right;
    position: relative;
    display: inline-flex;
    padding-block: 0.3em;
    margin-block: -0.3em;
  }

  :is([dir="rtl"]) .row {
    --morph-to: left;
  }

  .row[data-morphing] {
    mask-image: linear-gradient(to var(--morph-to), #000 calc(100% - var(--morph-fade)), transparent);
  }

  /* A filter (the blur on arriving and leaving letters) paints only inside
     the element's box, and a glyph's descender hangs below a tight line box.
     The block padding grows each letter's box to hold its descenders; the
     negative margin gives the room back, so nothing moves. */
  .glyph {
    display: inline-block;
    padding-block: 0.3em;
    margin-block: -0.3em;
  }

  .ghosts {
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  /* Sits where the letter sat: the row's block padding, held as the ghost's
     own padding so its blur has room for descenders too. */
  .ghost {
    position: absolute;
    top: 0;
    padding-block: 0.3em;
  }
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";
import styles from "./text-morph.module.css";

type Glyph = { key: string; char: string };
type Layout = { text: string; glyphs: Glyph[]; lefts: Map<string, number>; width: number };

const segmenter =
  typeof Intl !== "undefined" && "Segmenter" in Intl
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
    : null;

function split(text: string) {
  return segmenter ? Array.from(segmenter.segment(text), (s) => s.segment) : Array.from(text);
}

type Word = { start: number; end: number; text: string };

function words(chars: string[]): Word[] {
  const out: Word[] = [];
  let start = -1;
  chars.forEach((c, i) => {
    const space = /\s/.test(c);
    if (!space && start === -1) start = i;
    if (space && start !== -1) {
      out.push({ start, end: i, text: chars.slice(start, i).join("").toLowerCase() });
      start = -1;
    }
  });
  if (start !== -1) out.push({ start, end: chars.length, text: chars.slice(start).join("").toLowerCase() });
  return out;
}

/** Shared start and end letters: "Copy" → "Copied" keeps "Cop". */
function edges(a: string[], b: string[]): [number, number][] {
  const pairs: [number, number][] = [];
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) pairs.push([start, start++]);
  for (let k = 1; k <= Math.min(a.length, b.length) - start && a[a.length - k] === b[b.length - k]; k++) {
    pairs.push([a.length - k, b.length - k]);
  }
  return pairs;
}

/** Keys letters, reusing old keys for shared words and gap edges so they slide. */
function toGlyphs(prev: Glyph[] | null, text: string, generation: number): Glyph[] {
  // Same keys on the server and in the browser.
  const fresh = (i: number) => `${generation}:${i}`;
  const chars = split(text);
  if (!prev) return chars.map((char, i) => ({ key: fresh(i), char }));
  const keys: (string | null)[] = chars.map(() => null);
  const old = prev.map((g) => g.char);

  // Numbers match by place value, from the right.
  if (numeric(old.join("")) && numeric(text)) {
    for (let k = 1; k <= Math.min(old.length, chars.length); k++) {
      if (old[old.length - k] === chars[chars.length - k]) keys[chars.length - k] = prev[old.length - k].key;
    }
    return chars.map((char, i) => ({ key: keys[i] ?? fresh(i), char }));
  }

  const oldWords = words(old);
  const used = new Set<number>();
  const anchors: { from: Word; to: Word }[] = [];
  for (const w of words(chars)) {
    const i = oldWords.findIndex((o, k) => !used.has(k) && o.text === w.text);
    if (i === -1) continue;
    used.add(i);
    anchors.push({ from: oldWords[i], to: w });
    for (let k = 0; k < w.end - w.start; k++) {
      if (old[oldWords[i].start + k] === chars[w.start + k]) keys[w.start + k] = prev[oldWords[i].start + k].key;
    }
  }

  const ordered = anchors.every((a, i) => i === 0 || a.from.start > anchors[i - 1].from.end);
  if (ordered) {
    const bounds = [{ from: 0, to: 0 }, ...anchors.map((a) => ({ from: a.from.end, to: a.to.end }))];
    const ends = [...anchors.map((a) => ({ from: a.from.start, to: a.to.start })), { from: old.length, to: chars.length }];
    bounds.forEach((b, g) => {
      const pairs = edges(old.slice(b.from, ends[g].from), chars.slice(b.to, ends[g].to));
      for (const [i, j] of pairs) keys[b.to + j] = prev[b.from + i].key;
    });
  }

  return chars.map((char, i) => ({ key: keys[i] ?? fresh(i), char }));
}

const NUMERIC = /^[^\p{L}]*\d[^\p{L}]*$/u;
const numeric = (text: string) => NUMERIC.test(text);

const NUMBER = /[-\u2212]?\d[\d,.]*/;

function value(text: string) {
  const match = text.match(NUMBER);
  return match ? parseFloat(match[0].replace("\u2212", "-").replace(/,/g, "")) : NaN;
}

function direction(from: string, to: string) {
  const delta = value(to) - value(from);
  return Number.isNaN(delta) ? 0 : Math.sign(delta);
}

function token(el: Element, name: string, fallback: string) {
  return getComputedStyle(el).getPropertyValue(name).trim() || fallback;
}

function ms(value: string) {
  return value.endsWith("ms") ? parseFloat(value) : parseFloat(value) * 1000;
}

function translateX(el: Element) {
  const transform = getComputedStyle(el).transform;
  return transform && transform !== "none" ? new DOMMatrixReadOnly(transform).m41 : 0;
}

function measureText(row: HTMLElement, text: string, glyphs: Glyph[]): Layout {
  const node = row.firstChild;
  const origin = row.getBoundingClientRect().left;
  const lefts = new Map<string, number>();
  let width = 0;
  if (node?.nodeType === Node.TEXT_NODE) {
    const range = document.createRange();
    let offset = 0;
    for (const g of glyphs) {
      range.setStart(node, offset);
      range.setEnd(node, (offset += g.char.length));
      const box = range.getBoundingClientRect();
      lefts.set(g.key, box.left - origin);
      width = Math.max(width, box.right - origin);
    }
  }
  return { text, glyphs, lefts, width };
}

export function TextMorph({ children, className }: { children: string; className?: string }) {
  const [shown, setShown] = useState(children);
  const [state, setState] = useState(() => ({ generation: 0, glyphs: toGlyphs(null, children, 0) }));
  if (shown !== children) {
    setShown(children);
    setState((prev) => ({ generation: prev.generation + 1, glyphs: toGlyphs(prev.glyphs, children, prev.generation + 1) }));
  }
  const { glyphs } = state;
  // Plain text until the label first changes.
  const split = state.generation > 0;
  const rowRef = useRef<HTMLSpanElement>(null);
  const ghostsRef = useRef<HTMLSpanElement>(null);
  const layout = useRef<Layout | null>(null);

  useLayoutEffect(() => {
    const row = rowRef.current;
    const ghosts = ghostsRef.current;
    if (!row || !ghosts) return;

    if (!split) {
      layout.current = measureText(row, children, glyphs);
      return;
    }

    const nodes = new Map<string, HTMLElement>();
    for (const el of row.querySelectorAll<HTMLElement>("[data-glyph]")) nodes.set(el.dataset.glyph!, el);

    const last = layout.current;
    const lefts = new Map(glyphs.map((g) => [g.key, nodes.get(g.key)!.offsetLeft]));
    const tail = nodes.get(glyphs.at(-1)?.key ?? "");
    // Fractional, like the row's own width: offsetWidth rounds, and the
    // animation would end half a pixel short and then snap.
    const width = tail ? tail.getBoundingClientRect().right - row.getBoundingClientRect().left : 0;
    layout.current = { text: children, glyphs, lefts, width };

    if (!last || last.text === children) return;
    if (matchMedia("(prefers-reduced-motion: reduce)").matches) {
      ghosts.replaceChildren();
      return;
    }

    // The glide, not the move spring: a spring's overshoot narrows a button
    // past its new width and springs it back, which reads as the control
    // settling after the click. The glide lands once.
    const spring = token(row, "--ui-ease-glide", "cubic-bezier(0.22, 1, 0.36, 1)");
    const easeExit = token(row, "--ui-ease-exit", "cubic-bezier(0.4, 0, 1, 1)");
    const duration = ms(token(row, "--ui-dur-glide", "320ms"));
    const exit = ms(token(row, "--ui-dur-instant", "150ms"));
    // Letters arrive on the plain enter curve: a spring would bounce them
    // up and down, and vertical bounce reads as jitter in a line of text.
    const enter = token(row, "--ui-ease-enter", "cubic-bezier(0.2, 1, 0.3, 1)");

    // If a previous morph is still running, start from where it visibly is.
    const running = row.getAnimations();
    const fromWidth = running.length ? row.getBoundingClientRect().width : last.width;
    running.forEach((a) => a.cancel());
    const fade = Math.min(16, Math.abs(width - fromWidth));
    row.dataset.morphing = "";
    const grow = row.animate(
      { width: [`${fromWidth}px`, `${width}px`], ["--morph-fade" as string]: [`${fade}px`, "0px"] },
      { duration, easing: spring },
    );
    grow.finished.then(
      () => delete row.dataset.morphing,
      () => {}, // cancelled by a newer morph, which owns the flag now
    );

    const dir = direction(last.text, children) || 1;
    // A small rise with a soft blur: the change reads, the line holds still.
    const enterFrom = `translateY(${0.08 * dir}em)`;
    const leaveTo = `translateY(${-0.08 * dir}em)`;

    // Arrivals wait for leaving letters to clear.
    const current = new Set(glyphs.map((g) => g.key));
    const leaving = last.glyphs.some((g) => !current.has(g.key));
    const lead = exit * (leaving ? 0.85 : 0.4);
    let entering = 0;
    for (const g of glyphs) {
      const el = nodes.get(g.key)!;
      const before = last.lefts.get(g.key);
      if (before === undefined) {
        el.animate(
          {
            opacity: [0, 1],
            transform: [enterFrom, "none"],
            filter: ["blur(2px)", "none"],
          },
          { duration: duration * 0.75, easing: enter, delay: lead + entering++ * 15, fill: "backwards" },
        );
        continue;
      }
      // FLIP from where the letter is on screen now.
      const offset = before + translateX(el) - lefts.get(g.key)!;
      el.getAnimations().forEach((a) => a.cancel());
      if (Math.abs(offset) > 0.5) {
        el.animate({ transform: [`translateX(${offset}px)`, "none"] }, { duration, easing: spring });
      }
    }

    // Ghosts live in a layer React never renders into.
    const kept = new Set(glyphs.map((g) => g.key));
    for (const g of last.glyphs) {
      if (kept.has(g.key)) continue;
      const ghost = document.createElement("span");
      ghost.className = styles.ghost;
      ghost.textContent = g.char;
      ghost.style.left = `${last.lefts.get(g.key)}px`;
      ghosts.append(ghost);
      const fade = ghost.animate(
        {
          opacity: [1, 0],
          transform: ["none", leaveTo],
          filter: ["none", "blur(2px)"],
        },
        { duration: exit, easing: easeExit, fill: "forwards" },
      );
      fade.finished.then(
        () => ghost.remove(),
        () => ghost.remove(),
      );
    }
  }, [children, glyphs, split]);

  return (
    // The letter row must run in the label's own direction.
    <span className={className ? `${styles.root} ${className}` : styles.root} dir="auto">
      <span className={styles.label}>{children}</span>
      <span ref={rowRef} className={styles.row} aria-hidden="true">
        {split
          ? glyphs.map((g) => (
              <span key={g.key} data-glyph={g.key} className={styles.glyph}>
                {g.char}
              </span>
            ))
          : children}
        <span ref={ghostsRef} className={styles.ghosts} />
      </span>
    </span>
  );
}

import type { ComponentProps, ElementType } from "react";
import styles from "./button.module.css";

// No "use client", so it renders on the server and `as` can take a server-side link.
type ButtonLinkProps = ComponentProps<"a"> & {
  variant?: "primary" | "secondary" | "ghost" | "danger";
  size?: "sm" | "md" | "lg";
  /** Your router's link component, so navigation stays client-side. Defaults to a plain <a>. */
  as?: ElementType;
};

/** A link that looks like a button, for navigation. Same variants and sizes. */
export function ButtonLink({ variant = "primary", size = "md", as: Link = "a", className, children, ...props }: ButtonLinkProps) {
  return (
    <Link
      data-variant={variant}
      data-size={size}
      className={className ? `${styles.button} ${className}` : styles.button}
      {...props}
    >
      <span className={styles.content}>{children}</span>
    </Link>
  );
}

