export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

.name {
  composes: wrap from "../text/text.module.css";
}

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

@layer components {
  .block {
    --block-inset: var(--ui-space-2);
    --block-action: var(--ui-control-sm);
    /* Every box's radius; also the inset plus half the action, so the corner
       and the Copy pill stay concentric. */
    --block-radius: var(--ui-radius-lg);
    position: relative;
    min-width: 0;
    border-radius: var(--block-radius);
    background: var(--ui-surface);
    /* A box at rest, like a card: the one edge and the one soft shadow. */
    box-shadow: var(--ui-shadow-resting);
    font-family: var(--ui-font-sans);
  }

  .header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--ui-space-2);
    padding: var(--block-inset) var(--block-inset) var(--block-inset) var(--ui-space-5);
  }

  .name {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    font-weight: var(--ui-weight-medium);
    line-height: var(--ui-leading-md);
  }

  .actions {
    display: flex;
    align-items: center;
    flex-shrink: 0;
  }

  .action.action {
    padding-inline: var(--ui-space-3);
    color: var(--ui-muted);
  }

  @media (hover: hover) {
    .action.action:hover {
      color: var(--ui-foreground);
    }
  }

  .action.action[aria-pressed="true"] {
    --button-bg: var(--ui-fill);
    --button-bg-hover: var(--ui-fill-strong);
    color: var(--ui-foreground);
  }

  @media (pointer: coarse) {
    .block {
      --block-action: var(--ui-control-md);
    }
    .action.action {
      height: var(--block-action);
    }
  }

  /* ---------- Body ---------- */

  .scroller {
    position: relative;
    overflow: auto;
    overscroll-behavior-x: contain;
    border-radius: 0 0 var(--block-radius) var(--block-radius);
    scrollbar-width: thin;
    scrollbar-color: var(--ui-border-strong) transparent;
  }

  .scroller:focus-visible {
    outline: none;
  }

  /* Ring on the block: on the scroller the edge-fade mask would hide it. */
  .block:has(.scroller:focus-visible) {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .scroller[data-fade-end] {
    mask-image: linear-gradient(to left, transparent, black var(--ui-space-6));
  }

  .scroller[data-fade-start] {
    mask-image: linear-gradient(to right, transparent, black var(--ui-space-6));
  }

  .scroller[data-fade-start][data-fade-end] {
    mask-image: linear-gradient(
      to right,
      transparent,
      black var(--ui-space-6),
      black calc(100% - var(--ui-space-6)),
      transparent
    );
  }

  .pre {
    /* Keeps the right padding when scrolled. */
    width: max-content;
    min-width: 100%;
    margin: 0;
    padding: var(--ui-space-1) var(--ui-space-5) var(--ui-space-5);
    counter-reset: line;
  }

  .scroller[data-wrap] .pre {
    width: auto;
  }

  .code {
    display: block;
    color: var(--ui-foreground);
    font-family: var(--ui-font-mono);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-md);
    tab-size: 2;
    white-space: pre;
  }

  .scroller[data-wrap] .code {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
  }

  .line {
    display: block;
    min-height: 1lh;
  }

  /* Numbers are generated content so copying the code never picks them up. */
  .pre[data-numbers] .line {
    display: grid;
    grid-template-columns: calc(var(--digits) * 1ch) minmax(0, 1fr);
    column-gap: var(--ui-space-4);
  }

  .pre[data-numbers] .line::before {
    content: counter(line);
    counter-increment: line;
    color: var(--ui-subtle);
    font-variant-numeric: tabular-nums;
    text-align: end;
    user-select: none;
  }

  .scroller:not([data-wrap]) .pre[data-numbers] .line {
    grid-template-columns: calc(var(--digits) * 1ch) max-content;
  }

  /* ---------- Tokens ---------- */

  /* Four quiet hues from the accent and status text roles, the rest in the
     text grays. Keywords, strings, numbers and types carry the color; names
     (functions, properties) stay in the text color, so a block reads as text
     with a few marks rather than a rainbow. Mixes with the foreground go
     through oklab, so the gray adds no hue of its own; the one hue-to-hue mix
     goes through oklch, so blue and red meet at violet. 30-40% foreground in
     each keeps them calm and above 4.5:1 in both themes. */
  .block {
    --code-keyword: color-mix(in oklab, var(--ui-accent-text) 65%, var(--ui-foreground));
    --code-control: var(--code-keyword);
    --code-string: color-mix(in oklab, var(--ui-success-text) 65%, var(--ui-foreground));
    --code-number: color-mix(in oklab, var(--ui-warning-text) 70%, var(--ui-foreground));
    --code-function: var(--ui-foreground);
    --code-type: color-mix(
      in oklab,
      color-mix(in oklch, var(--ui-danger-text) 60%, var(--ui-accent-text)) 60%,
      var(--ui-foreground)
    );
    --code-attr: color-mix(in oklab, var(--ui-accent-text) 35%, var(--ui-foreground));
    --code-property: var(--ui-foreground);
    --code-punctuation: var(--ui-muted);
    --code-comment: var(--ui-subtle);
  }

  .keyword {
    color: var(--code-keyword);
  }

  .control {
    color: var(--code-control);
  }

  .string {
    color: var(--code-string);
  }

  .number,
  .literal,
  .value {
    color: var(--code-number);
  }

  .function {
    color: var(--code-function);
  }

  .type,
  .tag,
  .selector {
    color: var(--code-type);
  }

  .attr,
  .variable {
    color: var(--code-attr);
  }

  .property,
  .key {
    color: var(--code-property);
  }

  .punctuation {
    color: var(--code-punctuation);
  }

  .comment {
    color: var(--code-comment);
  }

  /* ---------- Streaming ---------- */

  .block[aria-busy] .line > span > span {
    animation: code-in var(--ui-dur-base) var(--ui-ease-enter) backwards;
  }

  @keyframes code-in {
    from {
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .block[aria-busy] .line > span > span {
      animation: none;
    }
  }
}

"use client";

import {
  memo,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
} from "react";
import { Button } from "../button/button";
import { Icon } from "../icons/icons";
import { TextMorph } from "../text-morph/text-morph";
import { canTokenize, tokenizeLine, type LineState, type Token } from "./tokenize";
import styles from "./code-block.module.css";

export { tokenizeLine, canTokenize } from "./tokenize";
export type { Token, TokenType, LineState } from "./tokenize";

const LANGUAGE_NAMES: Record<string, string> = {
  ts: "TypeScript", tsx: "TSX", typescript: "TypeScript",
  js: "JavaScript", jsx: "JSX", javascript: "JavaScript", mjs: "JavaScript", cjs: "JavaScript",
  py: "Python", python: "Python",
  sh: "Shell", bash: "Bash", shell: "Shell", zsh: "Zsh", console: "Terminal",
  json: "JSON", jsonc: "JSON",
  css: "CSS",
};

type CodeBlockProps = {
  /** The source. While streaming, pass the text so far; only append. */
  code: string;
  /** `ts`, `py`, `sh`, `json`… */
  language?: string;
  /** Header text instead of the language name, e.g. a file name. */
  title?: string;
  lineNumbers?: boolean;
  defaultWrap?: boolean;
  /** Text is still arriving; sets `aria-busy`. */
  streaming?: boolean;
  /** Use the built-in tokenizer when the language is supported. */
  highlight?: boolean;
  /** Trusted HTML per line from your highlighter; same lines as `code`. */
  lineHtml?: string[];
  maxHeight?: CSSProperties["maxHeight"];
  className?: string;
};

// Stable token arrays let memoized lines skip re-rendering.
const tokenCache = new Map<string, { tokens: Token[]; state: LineState }>();

function cachedTokens(text: string, language: string, state: LineState) {
  const key = `${language}\u0000${state}\u0000${text}`;
  let hit = tokenCache.get(key);
  if (!hit) {
    if (tokenCache.size > 5000) tokenCache.clear();
    hit = tokenizeLine(text, language, state);
    tokenCache.set(key, hit);
  }
  return hit;
}

type CopyState = "idle" | "copied" | "failed";

export function CodeBlock({
  code,
  language,
  title,
  lineNumbers = false,
  defaultWrap = false,
  streaming = false,
  highlight = true,
  lineHtml,
  maxHeight,
  className,
}: CodeBlockProps) {
  const [wrap, setWrap] = useState(defaultWrap);
  const [copy, setCopy] = useState<CopyState>("idle");
  const [overflow, setOverflow] = useState({ start: false, end: false, y: false });
  const scrollerRef = useRef<HTMLDivElement>(null);
  const atBottom = useRef(true);
  const copyTimer = useRef(0);

  const name = title ?? (language ? (LANGUAGE_NAMES[language.toLowerCase()] ?? language) : "Code");
  // While streaming, show only whole words.
  const shown = streaming ? code.slice(0, code.search(/\s\S*$/) + 1) : code;
  const lines = useMemo(() => shown.split("\n"), [shown]);
  const tokenize = highlight && !lineHtml && canTokenize(language);

  const lineTokens = useMemo(() => {
    if (!tokenize) return null;
    let state: LineState = "";
    return lines.map((text, i) => {
      // Not cached: the last line is still being written.
      const hit = i < lines.length - 1 ? cachedTokens(text, language!, state) : tokenizeLine(text, language!, state);
      state = hit.state;
      return hit.tokens;
    });
  }, [tokenize, lines, language]);

  const measure = useCallback(() => {
    const el = scrollerRef.current;
    if (!el) return;
    const max = el.scrollWidth - el.clientWidth;
    const left = Math.abs(el.scrollLeft);
    const next = { start: left > 1, end: max - left > 1, y: el.scrollHeight - el.clientHeight > 1 };
    atBottom.current = el.scrollHeight - el.scrollTop - el.clientHeight < 8;
    setOverflow((prev) => (prev.start === next.start && prev.end === next.end && prev.y === next.y ? prev : next));
  }, []);

  useEffect(() => {
    const el = scrollerRef.current;
    if (!el) return;
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    if (el.firstElementChild) observer.observe(el.firstElementChild);
    return () => observer.disconnect();
  }, [measure]);

  useLayoutEffect(() => {
    const el = scrollerRef.current;
    if (el && maxHeight !== undefined && streaming && atBottom.current) el.scrollTop = el.scrollHeight;
  }, [code, maxHeight, streaming]);

  useEffect(() => () => clearTimeout(copyTimer.current), []);

  async function handleCopy() {
    clearTimeout(copyTimer.current);
    try {
      if (!navigator.clipboard) throw new Error("Clipboard unavailable");
      await navigator.clipboard.writeText(code);
      setCopy("copied");
    } catch {
      setCopy("failed");
    }
    copyTimer.current = window.setTimeout(() => setCopy("idle"), 2000);
  }

  const scrollable = (!wrap && (overflow.start || overflow.end)) || overflow.y;
  const digits = String(lines.length).length;

  return (
    <div className={className ? `${styles.block} ${className}` : styles.block} aria-busy={streaming || undefined}>
      <div className={styles.header}>
        <span className={styles.name} title={name}>
          {name}
        </span>
        <div className={styles.actions}>
          <Button
            variant="ghost"
            size="sm"
            className={styles.action}
            aria-pressed={wrap}
            onClick={() => setWrap((w) => !w)}
          >
            Wrap
          </Button>
          <Button variant="ghost" size="sm" className={styles.action} onClick={handleCopy} aria-label={`Copy ${name} code`}>
            <Icon name={copy === "copied" ? "check" : "copy"} />
            <TextMorph>{copy === "copied" ? "Copied" : copy === "failed" ? "Copy failed" : "Copy"}</TextMorph>
          </Button>
          <span role="status" className={styles.srOnly}>
            {copy === "copied" ? "Copied to clipboard" : copy === "failed" ? "Couldn’t copy. Select the code and copy it manually." : ""}
          </span>
        </div>
      </div>

      <div
        ref={scrollerRef}
        className={styles.scroller}
        data-wrap={wrap || undefined}
        data-fade-start={(!wrap && overflow.start) || undefined}
        data-fade-end={(!wrap && overflow.end) || undefined}
        style={{ maxHeight }}
        onScroll={measure}
        // Focusable only when scrollable, so the keyboard can scroll it.
        tabIndex={scrollable ? 0 : undefined}
        role={scrollable ? "region" : undefined}
        aria-label={scrollable ? `${name} code` : undefined}
      >
        <pre className={styles.pre} data-numbers={lineNumbers || undefined} style={{ "--digits": digits } as CSSProperties}>
          <code className={styles.code}>
            {lines.map((text, i) => (
              <Line
                key={i}
                text={text}
                tokens={lineTokens?.[i]}
                html={lineHtml?.[i]}
                live={streaming && i === lines.length - 1}
              />
            ))}
          </code>
        </pre>
      </div>
    </div>
  );
}

type LineProps = { text: string; tokens?: Token[]; html?: string; live: boolean };

// Per-word spans keyed by offset, so each word fades in once.
const WORD = /\S+\s*|\s+/g;

const Line = memo(function Line({ text, tokens, html, live }: LineProps) {
  let offset = 0;
  const words = (t: Token) => {
    const from = offset;
    offset += t.text.length;
    return Array.from(t.text.matchAll(WORD), (m) => (
      <span key={from + m.index} className={t.type === "plain" ? undefined : styles[t.type]}>
        {m[0]}
      </span>
    ));
  };
  return (
    <span className={styles.line}>
      <span>
        {html !== undefined ? (
          <span dangerouslySetInnerHTML={{ __html: html }} />
        ) : tokens && live ? (
          tokens.flatMap(words)
        ) : tokens ? (
          tokens.map((t, i) =>
            t.type === "plain" ? (
              t.text
            ) : (
              <span key={i} className={styles[t.type]}>
                {t.text}
              </span>
            ),
          )
        ) : (
          text
        )}
      </span>
    </span>
  );
});

/** A small line tokenizer. A line's tokens depend only on its text and start state. */

/**
 * - `keyword`: declarations and operators (`const`, `import`, `typeof`); CSS pseudo-classes.
 * - `control`: flow (`if`, `return`, `await`); CSS at-rules; shell `if`, `then`.
 * - `literal`: `true`, `false`, `null`, `undefined`, `this`; Python `None`, `self`.
 * - `function`: a name that's called or declared as one; a shell command; a CSS function.
 * - `type`: PascalCase names, primitive types after `:`, names after `class`, `new`, `extends`.
 * - `property`: a name after `.`, or an object key.
 * - `tag` / `attr`: JSX tag and attribute names; CSS element selectors and `[attr]`; shell flags are `attr`.
 * - `selector`: CSS `.class` and `#id`.
 * - `variable`: shell `$VAR`; CSS custom properties.
 * - `key`: a JSON key or a CSS property name. `value`: a word in a CSS value.
 * - `punctuation`: brackets, operators, separators.
 */
export type TokenType =
  | "plain"
  | "keyword"
  | "control"
  | "string"
  | "comment"
  | "number"
  | "literal"
  | "function"
  | "type"
  | "property"
  | "tag"
  | "attr"
  | "selector"
  | "variable"
  | "key"
  | "value"
  | "punctuation";
export type Token = { type: TokenType; text: string };
/**
 * Carried from one line to the next. `""` means nothing is open. `jsx:…` is
 * the stack of open JSX tags, children and `{…}` expressions; `sh-args`
 * follows a shell line that ended in `\`; `css-value` a CSS value that runs
 * onto the next line.
 */
export type LineState =
  | ""
  | "block-comment"
  | "template"
  | 'triple"'
  | "triple'"
  | "sh-args"
  | "css-value"
  | `jsx:${string}`;

type Family = "js" | "py" | "sh" | "json" | "css";

const FAMILIES: Record<string, Family> = {
  js: "js", jsx: "js", javascript: "js", mjs: "js", cjs: "js",
  ts: "js", tsx: "js", typescript: "js",
  py: "py", python: "py",
  sh: "sh", bash: "sh", shell: "sh", zsh: "sh", console: "sh",
  json: "json", jsonc: "json",
  css: "css",
};

/** Languages whose `<Name` can open a JSX tag. Plain TS has generics there instead. */
const JSX = new Set(["js", "jsx", "javascript", "mjs", "cjs", "tsx"]);

const words = (list: string) => new Set(list.split(" "));

const JS_KEYWORDS = words(
  "class const default delete enum export extends function implements import in instanceof interface keyof let new private protected public typeof var void",
);
/** Keywords only when followed by a name, so `item.type` and `const from = 1` stay plain. */
const JS_CONTEXTUAL = words(
  "abstract accessor as asserts async declare from get infer is module namespace of override readonly satisfies set static type unique",
);
const JS_CONTROL = words(
  "await break case catch continue debugger do else finally for if return switch throw try while with yield",
);
const JS_LITERALS = words("true false null undefined this super NaN Infinity");
const JS_PRIMITIVES = words("string number boolean any unknown never object bigint symbol");
/** The name after one of these is a type. */
const JS_TYPE_INTRO = words("class interface type enum extends implements new namespace keyof typeof satisfies as is");

const PY_KEYWORDS = words("and as class def del from global import in is lambda nonlocal not or pass async");
const PY_CONTROL = words(
  "assert await break case continue elif else except finally for if match raise return try while with yield",
);
const PY_LITERALS = words("True False None self cls");

const SH_CONTROL = words("if then else elif fi for while until do done case esac function in select return");
/** These run the command that follows them. */
const SH_PREFIX = words("sudo time exec command env nohup xargs");

/** Whether `language` has a tokenizer. */
export function canTokenize(language: string | undefined) {
  return !!language && language.toLowerCase() in FAMILIES;
}

const NUMBER = /^(?:0[xX][\da-fA-F_]+|0[bB][01_]+|(?:\d[\d_]*\.?[\d_]*|\.\d[\d_]*)(?:[eE][+-]?\d+)?n?)/;
const WORD = /^[A-Za-z_$][\w$]*/;
// Hyphens included, so `--ui-space-3` is one word and its 3 isn't a number.
const CSS_WORD = /^-{0,2}[A-Za-z_][\w-]*/;
const CSS_UNIT = /^(?:%|[a-zA-Z]+)/;
const PUNCT = /^(?:=>|\?\?=?|\?\.|\.\.\.|[=!]==?|[<>]=?|&&=?|\|\|=?|\*\*|[-+*/%&|^~!?:;,.(){}[\]<>=@#\\])/;
const PASCAL = /^[A-Z](?:[\w$]*[a-z][\w$]*)?$/;

export function tokenizeLine(line: string, language: string, state: LineState = ""): { tokens: Token[]; state: LineState } {
  const lang = language.toLowerCase();
  const family = FAMILIES[lang];
  if (!family) return { tokens: [{ type: "plain", text: line }], state: "" };

  const tokens: Token[] = [];
  const push = (type: TokenType, text: string) => {
    if (!text) return;
    const last = tokens.at(-1);
    if (last && last.type === type) last.text += text;
    else tokens.push({ type, text });
  };
  const emit = (inner: Token[]) => inner.forEach((t) => push(t.type, t.text));

  if (family === "css") return { tokens, state: css(line, state, push) };
  if (family === "sh") return shell(line, lang, state, tokens, push);

  let i = 0;
  // Open JSX contexts: "t" in a tag, "x" in children, "e<n>" in a {…} expression n braces deep.
  const stack: string[] = state.startsWith("jsx:") ? state.slice(4).split(",") : [];
  const jsx = family === "js" && JSX.has(lang);

  if (state === "block-comment" || state === 'triple"' || state === "triple'") {
    const close = state === "block-comment" ? "*/" : state === 'triple"' ? '"""' : "'''";
    const end = findClose(line, 0, close, state !== "block-comment");
    const type = state === "block-comment" ? "comment" : "string";
    if (end === -1) {
      push(type, line);
      return { tokens, state };
    }
    push(type, line.slice(0, end));
    i = end;
  } else if (state === "template") {
    const end = template(line, 0, lang, push, emit);
    if (end === -1) return { tokens, state };
    i = end;
  }

  while (i < line.length) {
    const rest = line.slice(i);
    const ch = line[i];
    const prev = i > 0 ? line[i - 1] : "";
    const frame = stack.at(-1);

    // ---------- JSX ----------
    if (frame === "x" || frame === "t" || (jsx && ch === "<" && jsxStarts(line, i))) {
      const close = /^<\/\s*([A-Za-z][\w.:-]*)?\s*>/.exec(rest);
      if (ch === "<" && close) {
        const name = close[1] ?? "";
        const at = close[0].indexOf(name, 2);
        push("punctuation", close[0].slice(0, name ? at : close[0].length - 1));
        push("tag", name);
        push("punctuation", name ? close[0].slice(at + name.length) : ">");
        if (stack.at(-1) === "x") stack.pop();
        i += close[0].length;
        continue;
      }
      const open = /^<([A-Za-z][\w.:-]*)?/.exec(rest);
      if (ch === "<" && open && (open[1] || line[i + 1] === ">")) {
        push("punctuation", "<");
        if (open[1]) {
          push("tag", open[1]);
          stack.push("t");
          i += open[0].length;
        } else {
          push("punctuation", ">");
          stack.push("x");
          i += 2;
        }
        continue;
      }
      if (frame === "x") {
        if (ch === "{") {
          push("punctuation", ch);
          stack.push("e1");
          i++;
          continue;
        }
        const text = /^[^<{]+/.exec(rest)?.[0] ?? ch;
        push("plain", text);
        i += text.length;
        continue;
      }
      if (frame === "t") {
        if (rest.startsWith("/>")) {
          push("punctuation", "/>");
          stack.pop();
          i += 2;
          continue;
        }
        if (ch === ">") {
          push("punctuation", ch);
          stack[stack.length - 1] = "x";
          i++;
          continue;
        }
        if (ch === "{") {
          push("punctuation", ch);
          stack.push("e1");
          i++;
          continue;
        }
        if (ch === '"' || ch === "'") {
          const end = findClose(line, i + 1, ch, false);
          const stop = end === -1 ? line.length : end;
          push("string", line.slice(i, stop));
          i = stop;
          continue;
        }
        const attr = /^[A-Za-z_$][\w$:.-]*/.exec(rest);
        if (attr) {
          push("attr", attr[0]);
          i += attr[0].length;
          continue;
        }
        push(/\s/.test(ch) ? "plain" : "punctuation", ch);
        i++;
        continue;
      }
    }

    // A {…} expression inside JSX ends at its matching brace.
    if (frame?.startsWith("e") && (ch === "{" || ch === "}")) {
      const depth = Number(frame.slice(1)) + (ch === "{" ? 1 : -1);
      if (depth === 0) stack.pop();
      else stack[stack.length - 1] = `e${depth}`;
      push("punctuation", ch);
      i++;
      continue;
    }

    // ---------- Comments ----------
    if ((family === "js" || family === "json") && rest.startsWith("//")) {
      push("comment", rest);
      break;
    }
    if ((family === "js" || family === "json") && rest.startsWith("/*")) {
      const end = findClose(line, i + 2, "*/", false);
      if (end === -1) {
        push("comment", rest);
        return { tokens, state: "block-comment" };
      }
      push("comment", line.slice(i, end));
      i = end;
      continue;
    }
    if (family === "py" && ch === "#") {
      push("comment", rest);
      break;
    }

    // ---------- Strings ----------
    if (family === "py" && (rest.startsWith('"""') || rest.startsWith("'''"))) {
      const quote = rest.slice(0, 3);
      const end = findClose(line, i + 3, quote, true);
      if (end === -1) {
        push("string", rest);
        return { tokens, state: quote === '"""' ? 'triple"' : "triple'" };
      }
      push("string", line.slice(i, end));
      i = end;
      continue;
    }
    if (ch === "`" && family === "js") {
      push("string", "`");
      const end = template(line, i + 1, lang, push, emit);
      if (end === -1) return { tokens, state: "template" };
      i = end;
      continue;
    }
    if (ch === '"' || (ch === "'" && family !== "json")) {
      let end = findClose(line, i + 1, ch, true);
      if (end === -1) end = line.length;
      const isKey = family === "json" && /^\s*:/.test(line.slice(end));
      push(isKey ? "key" : "string", line.slice(i, end));
      i = end;
      continue;
    }

    // ---------- Numbers ----------
    if (/[\d.]/.test(ch) && !/[\w$]/.test(prev)) {
      const match = NUMBER.exec(rest);
      if (match && match[0] !== ".") {
        push("number", match[0]);
        i += match[0].length;
        continue;
      }
    }

    // ---------- Words ----------
    if (family === "py" && ch === "@" && WORD.test(line.slice(i + 1)) && !line.slice(0, i).trim()) {
      const name = WORD.exec(line.slice(i + 1))![0];
      push("function", "@" + name);
      i += name.length + 1;
      continue;
    }
    const word = WORD.exec(rest);
    if (word) {
      const w = word[0];
      const after = line.slice(i + w.length);
      push(family === "js" ? jsWord(w, line, i, after) : family === "py" ? pyWord(w, line, i, after) : jsonWord(w), w);
      i += w.length;
      continue;
    }

    const punct = PUNCT.exec(rest);
    if (punct) {
      push("punctuation", punct[0]);
      i += punct[0].length;
      continue;
    }
    push("plain", ch);
    i++;
  }

  return { tokens, state: stack.length ? `jsx:${stack.join(",")}` : "" };
}

/** The last non-space character before `i`, or `""` at the start of the line. */
function before(line: string, i: number) {
  return /(\S)\s*$/.exec(line.slice(0, i))?.[1] ?? "";
}

/** The word just before `i`, skipping spaces. */
function wordBefore(line: string, i: number) {
  return /([A-Za-z_$][\w$]*)\s*$/.exec(line.slice(0, i))?.[1] ?? "";
}

/** `<` opens JSX where an expression can start: after `(`, `=`, `return`, `&&`, `?`… or at a line's start. */
function jsxStarts(line: string, i: number) {
  if (!/[A-Za-z>]/.test(line[i + 1] ?? "")) return false;
  const b = before(line, i);
  if (!b || "([{,;=?:&|>!}".includes(b)) return true;
  return /\b(?:return|yield|default|case)$/.test(line.slice(0, i).trimEnd());
}

function jsWord(w: string, line: string, i: number, after: string): TokenType {
  const b = before(line, i);
  const called = /^\s*(?:\?\.)?\(/.test(after) || /^<[\w\s,.[\]|&]*>\(/.test(after);
  if (b === "." && line[i - 1] === ".") {
    if (called) return "function";
    return PASCAL.test(w) ? "type" : "property";
  }
  if (b === "." && line.slice(i - 2, i) === "?.") return called ? "function" : "property";
  // An object or type-literal key: `{ kind: "fee" }`, `onSend?: () => void`.
  if (/^\??:(?!:)/.test(after.trimStart()) && (!b || "{,;".includes(b)) && !JS_CONTROL.has(w) && w !== "default") {
    return "property";
  }
  if (JS_LITERALS.has(w)) return "literal";
  if (JS_CONTROL.has(w)) return "control";
  if (JS_KEYWORDS.has(w)) return "keyword";
  if (JS_CONTEXTUAL.has(w) && /^\s+[\w$*{["'`]/.test(after) && !/^\s+(?:in|of|instanceof)\b/.test(after)) {
    return "keyword";
  }
  const prevWord = b && /[\w$]/.test(b) ? wordBefore(line, i) : "";
  if (JS_TYPE_INTRO.has(prevWord) && prevWord !== "type") return PASCAL.test(w) || prevWord !== "new" ? "type" : "plain";
  if (prevWord === "type" && /^\s*[=<]/.test(after)) return "type";
  if (called) return prevWord === "new" ? "type" : "function";
  if (prevWord === "function") return "function";
  if (PASCAL.test(w)) return "type";
  if (JS_PRIMITIVES.has(w) && (":|&<,=([".includes(b) || prevWord === "keyof" || prevWord === "extends")) return "type";
  return "plain";
}

function pyWord(w: string, line: string, i: number, after: string): TokenType {
  const b = before(line, i);
  const called = /^\s*\(/.test(after);
  if (b === "." && line[i - 1] === ".") return called ? "function" : PASCAL.test(w) ? "type" : "property";
  if (PY_LITERALS.has(w)) return "literal";
  if (PY_CONTROL.has(w)) return "control";
  if (PY_KEYWORDS.has(w)) return "keyword";
  const prevWord = b && /\w/.test(b) ? wordBefore(line, i) : "";
  if (prevWord === "def") return "function";
  if (prevWord === "class") return "type";
  if (called) return PASCAL.test(w) ? "type" : "function";
  if (PASCAL.test(w)) return "type";
  return "plain";
}

function jsonWord(w: string): TokenType {
  return w === "true" || w === "false" || w === "null" ? "literal" : "plain";
}

/**
 * Pushes a template literal's body from `from`, with `${…}` tokenized as
 * code. Returns the index past the closing backtick, or -1 if the line ends
 * first (an interpolation that runs past the line stays string-colored).
 */
function template(
  line: string,
  from: number,
  lang: string,
  push: (type: TokenType, text: string) => void,
  emit: (tokens: Token[]) => void,
) {
  let start = from;
  for (let j = from; j < line.length; j++) {
    if (line[j] === "\\") {
      j++;
      continue;
    }
    if (line[j] === "`") {
      push("string", line.slice(start, j + 1));
      return j + 1;
    }
    if (line.startsWith("${", j)) {
      const end = matchBrace(line, j + 2);
      if (end === -1) break;
      push("string", line.slice(start, j));
      push("punctuation", "${");
      // `ts` so a `<` inside isn't read as JSX.
      emit(tokenizeLine(line.slice(j + 2, end), lang === "tsx" || lang === "jsx" ? "ts" : lang).tokens);
      push("punctuation", "}");
      j = end;
      start = end + 1;
    }
  }
  push("string", line.slice(start));
  return -1;
}

/** Index of the `}` that closes a brace opened just before `from`, skipping strings. -1 if none on the line. */
function matchBrace(line: string, from: number) {
  let depth = 1;
  for (let j = from; j < line.length; j++) {
    const c = line[j];
    if (c === '"' || c === "'" || c === "`") {
      const end = findClose(line, j + 1, c, true);
      if (end === -1) return -1;
      j = end - 1;
    } else if (c === "{") depth++;
    else if (c === "}" && --depth === 0) return j;
  }
  return -1;
}

// ---------- Shell ----------

function shell(
  line: string,
  lang: string,
  state: LineState,
  tokens: Token[],
  push: (type: TokenType, text: string) => void,
): { tokens: Token[]; state: LineState } {
  let i = 0;
  let command = state !== "sh-args";
  if (lang === "console" && state !== "sh-args") {
    // Only prompt lines are commands; the rest is output.
    const prompt = /^\s*[$>]\s/.exec(line);
    if (!prompt) {
      push("plain", line);
      return { tokens, state: "" };
    }
    push("punctuation", prompt[0]);
    i = prompt[0].length;
  }

  while (i < line.length) {
    const rest = line.slice(i);
    const ch = line[i];
    const prev = i > 0 ? line[i - 1] : "";

    if (/\s/.test(ch)) {
      const space = /^\s+/.exec(rest)![0];
      push("plain", space);
      i += space.length;
      continue;
    }
    if (ch === "#" && (i === 0 || /\s/.test(prev))) {
      push("comment", rest);
      break;
    }
    if (rest === "\\") {
      push("punctuation", ch);
      return { tokens, state: "sh-args" };
    }
    if (ch === '"' || ch === "'") {
      // Single quotes have no escapes.
      let end = findClose(line, i + 1, ch, ch === '"');
      if (end === -1) end = line.length;
      push("string", line.slice(i, end));
      i = end;
      continue;
    }
    const variable = /^\$(?:\{[^}]*\}|[A-Za-z_]\w*|[\d#?@*$!-])/.exec(rest);
    if (variable) {
      push("variable", variable[0]);
      i += variable[0].length;
      continue;
    }
    const op = /^(?:\$\(|&&|\|\||[|;()&]|\d?>>?&?\d?|<)/.exec(rest);
    if (op) {
      push("punctuation", op[0]);
      i += op[0].length;
      if (!/[<>]/.test(op[0])) command = true;
      continue;
    }
    const word = /^[^\s|&;()<>'"`$]+/.exec(rest)?.[0] ?? ch;
    i += word.length;
    if (command) {
      const assign = /^([A-Za-z_]\w*)=(.*)$/.exec(word);
      if (assign) {
        push("variable", assign[1]);
        push("punctuation", "=");
        push("plain", assign[2]);
      } else if (SH_CONTROL.has(word)) {
        push("control", word);
        command = !/^(?:for|case|select|function|in)$/.test(word);
      } else {
        push("function", word);
        command = SH_PREFIX.has(word);
      }
    } else if (word.startsWith("-") && word.length > 1 && !/^-\d/.test(word)) {
      const eq = word.indexOf("=");
      push("attr", eq === -1 ? word : word.slice(0, eq));
      if (eq !== -1) {
        push("punctuation", "=");
        push("plain", word.slice(eq + 1));
      }
    } else if (SH_CONTROL.has(word) && word === "in") {
      push("control", word);
    } else {
      push(/^-?\d+(?:\.\d+)?$/.test(word) ? "number" : "plain", word);
    }
  }
  return { tokens, state: "" };
}

// ---------- CSS ----------

/** Pushes a CSS line's tokens and returns the state it leaves open. */
function css(line: string, state: LineState, push: (type: TokenType, text: string) => void): LineState {
  let i = 0;
  if (state === "block-comment") {
    const end = findClose(line, 0, "*/", false);
    push("comment", end === -1 ? line : line.slice(0, end));
    if (end === -1) return state;
    i = end;
  }
  type Mode = "selector" | "value" | "prelude" | "start";
  // Before its first `{`, a line is a selector if it opens a block or lists
  // selectors (`a,`); otherwise it starts as declarations.
  const code = line.replace(/\/\*.*?(\*\/|$)/g, "");
  let selectorLine = state !== "css-value" && (/\{/.test(code) || (/,\s*$/.test(code) && !/:\s/.test(code)));
  let mode: Mode = state === "css-value" ? "value" : "start";
  let parens = 0;

  while (i < line.length) {
    const rest = line.slice(i);
    const ch = line[i];
    const prev = i > 0 ? line[i - 1] : "";

    if (rest.startsWith("/*")) {
      const end = findClose(line, i + 2, "*/", false);
      push("comment", end === -1 ? rest : line.slice(i, end));
      if (end === -1) return "block-comment";
      i = end;
      continue;
    }
    if (/\s/.test(ch)) {
      const space = /^\s+/.exec(rest)![0];
      push("plain", space);
      i += space.length;
      continue;
    }
    if (ch === '"' || ch === "'") {
      let end = findClose(line, i + 1, ch, true);
      if (end === -1) end = line.length;
      push("string", line.slice(i, end));
      i = end;
      continue;
    }
    if (ch === "{" || ch === "}" || ch === ";") {
      push("punctuation", ch);
      mode = "start";
      selectorLine = false;
      parens = 0;
      i++;
      continue;
    }
    const at = /^(?:@[\w-]+|!important\b)/.exec(rest);
    if (at) {
      push(at[0].startsWith("@") ? "control" : "keyword", at[0]);
      if (at[0].startsWith("@")) mode = "prelude";
      i += at[0].length;
      continue;
    }

    if (mode === "start" && (selectorLine || /^[^:;]*\{/.test(rest))) mode = "selector";

    if (mode === "selector") {
      const sel = /^(?:[.#][\w-]+|::?[\w-]+|&|\*)/.exec(rest);
      if (sel) {
        const s = sel[0];
        push(s[0] === ":" ? "keyword" : s === "&" || s === "*" ? "tag" : "selector", s);
        i += s.length;
        continue;
      }
      const attr = /^\[\s*([\w-]+)/.exec(rest);
      if (attr) {
        push("punctuation", attr[0].slice(0, attr[0].length - attr[1].length));
        push("attr", attr[1]);
        i += attr[0].length;
        continue;
      }
      const el = CSS_WORD.exec(rest);
      if (el) {
        push(/^(?:from|to)$/.test(el[0]) ? "keyword" : "tag", el[0]);
        i += el[0].length;
        continue;
      }
      push("punctuation", ch);
      i++;
      continue;
    }

    // Declarations, values and at-rule preludes.
    if (ch === "#" && mode === "value") {
      const hex = /^#[\da-fA-F]{3,8}\b/.exec(rest);
      if (hex) {
        push("number", hex[0]);
        i += hex[0].length;
        continue;
      }
    }
    const minus = ch === "-" && /[\d.]/.test(line[i + 1] ?? "") && !/[\w)-]/.test(prev);
    if ((minus || /[\d.]/.test(ch)) && !/[\w-]/.test(prev)) {
      const match = NUMBER.exec(minus ? rest.slice(1) : rest);
      if (match && match[0] !== ".") {
        const sign = minus ? "-" : "";
        const unit = CSS_UNIT.exec(rest.slice(sign.length + match[0].length))?.[0] ?? "";
        push("number", sign + match[0] + unit);
        i += sign.length + match[0].length + unit.length;
        continue;
      }
    }
    const name = CSS_WORD.exec(rest);
    if (name) {
      const n = name[0];
      const after = line.slice(i + n.length);
      if (mode === "start" && /^\s*:/.test(after)) {
        push(n.startsWith("--") ? "variable" : "key", n);
        const colon = after.indexOf(":") + 1;
        push("punctuation", after.slice(0, colon));
        i += n.length + colon;
        mode = "value";
        continue;
      }
      if (mode === "prelude" && parens > 0 && /^\s*:/.test(after)) push("key", n);
      else if (after.startsWith("(")) push("function", n);
      else if (n.startsWith("--")) push("variable", n);
      else if (mode === "prelude" && /^(?:and|or|not|only)$/.test(n)) push("keyword", n);
      else push("value", n);
      i += n.length;
      continue;
    }
    if (ch === "(") parens++;
    if (ch === ")") parens = Math.max(0, parens - 1);
    push("punctuation", ch);
    i++;
  }
  return mode === "value" ? "css-value" : "";
}

/** Index just past `close`, skipping backslash escapes. -1 if the line ends first. */
function findClose(line: string, from: number, close: string, escapes: boolean) {
  for (let i = from; i < line.length; i++) {
    if (escapes && line[i] === "\\") {
      i++;
      continue;
    }
    if (line.startsWith(close, i)) return i + close.length;
  }
  return -1;
}

@layer theme, base, components, utilities;

@layer components {
  /* An assistant's reply at chat scale: 15px text on a 1.6 line, blocks 12
     apart, headings, code and tables given more room. The first and last
     blocks carry no outer margin, so it sits flush in a bubble. */
  .root {
    min-width: 0;
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-prose) var(--ui-font-sans);
    overflow-wrap: break-word;
    hanging-punctuation: first;
  }

  /* ---------- Rhythm ---------- */

  /* Every block container (the reply, a quote, a list item) spaces its
     children the same way: margin on top only, never below. */
  :is(.root, .quote, .item, .taskBody) > * {
    margin-block: 0;
  }

  :is(.root, .quote, .item, .taskBody) > * + * {
    margin-top: var(--ui-space-3);
  }

  /* A lead-in line and its list read as one thought. */
  :is(.root, .quote, .item, .taskBody) > p + .list {
    margin-top: var(--ui-space-2);
  }

  /* A nested list hangs right under its item's text. */
  :is(.item, .taskBody) > .list {
    margin-top: var(--ui-space-1);
  }

  /* Boxes take more room on both sides, rules more again. */
  :is(.root, .quote, .item, .taskBody) > * + :is(.code, .table),
  :is(.root, .quote, .item, .taskBody) > :is(.code, .table) + * {
    margin-top: var(--ui-space-4);
  }

  :is(.root, .quote, .item, .taskBody) > * + .rule,
  :is(.root, .quote, .item, .taskBody) > .rule + * {
    margin-top: var(--ui-space-5);
  }

  /* A heading sits closer to what it introduces than to what came before. */
  :is(.root, .quote, .item, .taskBody) > * + .heading {
    margin-top: var(--ui-space-5);
  }

  :is(.root, .quote, .item, .taskBody) > .heading + * {
    margin-top: var(--ui-space-2);
  }

  /* ---------- Headings ---------- */

  /* Four sizes at most (typography.md): # is the 22px heading step, ## and
     ### the body size in a heavier weight, #### a muted label. */
  .heading {
    color: var(--ui-foreground);
    font-size: var(--ui-text-md);
    font-weight: var(--ui-weight-semibold);
    line-height: var(--ui-leading-md);
    text-wrap: balance;
  }

  .heading[data-depth="1"] {
    font-size: var(--ui-text-2xl);
    line-height: var(--ui-leading-2xl);
    letter-spacing: var(--ui-tracking-heading);
  }

  .root > * + .heading[data-depth="1"] {
    margin-top: var(--ui-space-6);
  }

  .root > * + .heading[data-depth="3"] {
    margin-top: var(--ui-space-4);
  }

  .heading[data-depth="4"] {
    color: var(--ui-muted);
    font-weight: var(--ui-weight-medium);
  }

  /* ---------- Inline ---------- */

  .root strong {
    font-weight: var(--ui-weight-semibold);
  }

  .root del {
    color: var(--ui-muted);
  }

  .inlineCode {
    padding: 2px 5px;
    border-radius: calc(var(--ui-radius-sm) / 2);
    background: var(--ui-fill);
    font-family: var(--ui-font-mono);
    font-size: var(--ui-text-code);
    /* A path or identifier with nowhere to break still fits a phone. */
    overflow-wrap: anywhere;
  }

  .link {
    color: inherit;
    text-decoration-line: underline;
    text-decoration-color: var(--ui-subtle);
    text-decoration-thickness: from-font;
    text-underline-offset: 3px;
    transition: text-decoration-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    a.link:hover {
      text-decoration-color: currentColor;
    }
  }

  /* ---------- Lists ---------- */

  .list {
    padding-inline-start: var(--ui-space-5);
  }

  /* Set, not inherited from the browser: a reset such as Tailwind's
     preflight clears list-style on every ul and ol. */
  ul.list {
    list-style: disc outside;
  }

  ol.list {
    list-style: decimal outside;
  }

  .item {
    padding-inline-start: 2px;
  }

  .list > .item + .item {
    margin-top: var(--ui-space-1);
  }

  /* A loose list (blank lines between items) keeps paragraph spacing. */
  .list:not([data-tight]) > .item + .item {
    margin-top: var(--ui-space-3);
  }

  .item::marker {
    color: var(--ui-subtle);
    font-variant-numeric: tabular-nums;
  }

  /* A task: the box sits where the bullet would, on the first line. */
  .item[data-task] {
    display: flex;
    align-items: flex-start;
    gap: var(--ui-space-2);
    margin-inline-start: calc(var(--ui-space-5) * -1);
    padding-inline-start: 0;
    list-style: none;
  }

  /* Centered on the first line: the box alone has no text to align by. */
  .task.task {
    flex-shrink: 0;
    margin-top: calc((1lh - var(--checkbox-size)) / 2);
    cursor: default;
  }

  .item[data-task] > .taskBody {
    flex: 1;
    min-width: 0;
    margin-top: 0;
  }

  /* ---------- Quote ---------- */

  .quote {
    margin-inline: 0;
    padding-inline-start: var(--ui-space-4);
    /* Running text, not a pull quote: pretty, not balanced. */
    text-wrap: pretty;
    color: var(--ui-muted);
    box-shadow: inset var(--ui-hairline) 0 0 var(--ui-border-strong);
  }

  :is([dir="rtl"]) .quote {
    box-shadow: inset calc(var(--ui-hairline) * -1) 0 0 var(--ui-border-strong);
  }

  /* ---------- Rule ---------- */

  .rule {
    height: var(--ui-hairline);
    border: 0;
    box-shadow: inset 0 var(--ui-hairline) 0 var(--ui-border);
  }

  /* ---------- Code ---------- */

  /* ---------- Table ---------- */

  /* The kit's table: a box at rest with rows split by hairlines and no
     fills. It scrolls sideways on its own, fading the edge that has more. */
  .table {
    overflow-x: auto;
    overscroll-behavior-x: contain;
    border-radius: var(--ui-radius-md);
    background: var(--ui-surface);
    box-shadow: var(--ui-shadow-resting);
    scrollbar-width: thin;
    scrollbar-color: var(--ui-border-strong) transparent;
  }

  .table:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .table[data-fade-end] {
    mask-image: linear-gradient(to left, transparent, black var(--ui-space-6));
  }

  .table[data-fade-start] {
    mask-image: linear-gradient(to right, transparent, black var(--ui-space-6));
  }

  .table[data-fade-start][data-fade-end] {
    mask-image: linear-gradient(to right, transparent, black var(--ui-space-6), black calc(100% - var(--ui-space-6)), transparent);
  }

  .table table {
    width: 100%;
    border-collapse: collapse;
    font-variant-numeric: tabular-nums;
    line-height: var(--ui-leading-md);
  }

  .table :is(th, td) {
    min-width: 8rem;
    padding: var(--ui-space-2) var(--ui-space-4);
    text-align: start;
    vertical-align: top;
  }

  .table th {
    color: var(--ui-muted);
    font-weight: var(--ui-weight-medium);
    white-space: nowrap;
  }

  .table :is(th, td)[data-align="center"] {
    text-align: center;
  }

  .table :is(th, td)[data-align="right"] {
    text-align: end;
  }

  /* A line between rows, never above the first: the box's own edge is there. */
  .table :where(tr + tr > *, thead + tbody tr:first-child > *) {
    box-shadow: inset 0 var(--ui-hairline) 0 var(--ui-border);
  }

  /* ---------- Caret ---------- */

  /* A quiet bar after the last word while the reply streams. It breathes
     rather than blinks, and holds still under reduced motion. */
  .caret {
    display: inline-block;
    width: calc(var(--ui-hairline) * 2);
    height: 1.1em;
    margin-inline-start: 2px;
    border-radius: var(--ui-radius-full);
    background: var(--ui-muted);
    vertical-align: -0.2em;
    animation: caret var(--ui-dur-pulse) var(--ui-ease-pulse) infinite alternate;
  }

  /* In a tight list item the caret is the item's own child: keep the
     block rhythm's top margin off it, or the line would drop. */
  .root .caret {
    margin-block: 0;
  }

  @keyframes caret {
    to {
      opacity: 0.25;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .caret {
      animation: none;
    }

    .link {
      transition: none;
    }
  }

  @media (forced-colors: active) {
    .caret {
      background: CanvasText;
    }

    .quote {
      border-inline-start: 1px solid CanvasText;
    }

    .rule {
      border-top: 1px solid CanvasText;
    }
  }
}

"use client";

import {
  Fragment,
  memo,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ComponentProps,
  type ReactNode,
} from "react";
import { Checkbox } from "../checkbox/checkbox";
import { CodeBlock } from "../code-block/code-block";
import { parse, safeHref, type Block, type ListItem } from "./parse";
import styles from "./markdown.module.css";

export { parse, safeHref } from "./parse";
export type { Block, Section, ListItem, Align } from "./parse";

type MarkdownProps = Omit<ComponentProps<"div">, "children"> & {
  /** The reply so far. While streaming, pass the whole text each time. */
  source: string;
  /** Text is still arriving: unfinished syntax is held back or closed early, and a caret follows the last word. */
  streaming?: boolean;
  /** The tag a `#` heading renders as; deeper ones follow, up to h6. Default 3. */
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6;
};

export function Markdown({ source, streaming = false, headingLevel = 3, className, ...props }: MarkdownProps) {
  const sections = useMemo(() => parse(source, streaming), [source, streaming]);
  const last = sections.length - 1;

  return (
    <div
      {...props}
      className={className ? `${styles.root} ${className}` : styles.root}
      aria-busy={streaming || undefined}
    >
      {sections.map((s, i) => (
        <Section key={i} block={s.block} source={s.source} tail={streaming && i === last} level={headingLevel} />
      ))}
      {streaming && last < 0 && (
        <p>
          <Caret />
        </p>
      )}
    </div>
  );
}

// A finished block keeps its source, so it doesn't render again as text arrives below it.
const Section = memo(
  function Section({ block, tail, level }: { block: Block; source: string; tail: boolean; level: number }) {
    return renderBlock(block, tail, level, 0);
  },
  (a, b) => a.source === b.source && a.tail === b.tail && a.level === b.level,
);

function Caret() {
  return <span className={styles.caret} aria-hidden="true" />;
}

/** Inline content, with the caret after it when it's the last thing written. */
function Text({ text, tail }: { text: string; tail: boolean }) {
  return (
    <>
      {inline(text, tail)}
      {tail && <Caret />}
    </>
  );
}

const HEADINGS = ["h1", "h2", "h3", "h4", "h5", "h6"] as const;

function renderBlock(block: Block, tail: boolean, level: number, key: number): ReactNode {
  switch (block.type) {
    case "paragraph":
      return (
        <p key={key}>
          <Text text={block.text} tail={tail} />
        </p>
      );
    case "heading": {
      const Tag = HEADINGS[Math.min(level + block.depth - 2, 5)];
      return (
        <Tag key={key} className={styles.heading} data-depth={Math.min(block.depth, 4)}>
          <Text text={block.text} tail={tail} />
        </Tag>
      );
    }
    case "rule":
      return <hr key={key} className={styles.rule} />;
    case "code":
      return (
        <CodeBlock
          key={key}
          className={styles.code}
          code={block.code}
          language={block.language || undefined}
          streaming={tail && !block.closed}
        />
      );
    case "quote":
      return (
        <blockquote key={key} className={styles.quote}>
          {renderBlocks(block.children, tail, level)}
        </blockquote>
      );
    case "list": {
      const List = block.ordered ? "ol" : "ul";
      const lastItem = block.items.length - 1;
      return (
        <List
          key={key}
          className={styles.list}
          start={block.ordered && block.start !== 1 ? block.start : undefined}
          data-tight={block.tight || undefined}
        >
          {block.items.map((item, i) => (
            <Item key={i} item={item} tight={block.tight} tail={tail && i === lastItem} level={level} />
          ))}
        </List>
      );
    }
    case "table":
      return <Table key={key} block={block} />;
  }
}

function renderBlocks(blocks: Block[], tail: boolean, level: number, tight = false) {
  const last = blocks.length - 1;
  return blocks.map((b, i) =>
    // In a tight list an item's paragraph is just its text.
    tight && b.type === "paragraph" ? (
      <Text key={i} text={b.text} tail={tail && i === last} />
    ) : (
      renderBlock(b, tail && i === last, level, i)
    ),
  );
}

function Item({ item, tight, tail, level }: { item: ListItem; tight: boolean; tail: boolean; level: number }) {
  const body = renderBlocks(item.children, tail, level, tight);
  if (item.checked === null) return <li className={styles.item}>{body}</li>;
  return (
    <li className={styles.item} data-task="">
      <Checkbox
        className={styles.task}
        checked={item.checked}
        readOnly
        tabIndex={-1}
        aria-label={item.checked ? "Done" : "Not done"}
      />
      <div className={styles.taskBody}>{body}</div>
    </li>
  );
}

function Table({ block }: { block: Extract<Block, { type: "table" }> }) {
  const ref = useRef<HTMLDivElement>(null);
  const [edge, setEdge] = useState({ start: false, end: false });

  const measure = useCallback(() => {
    const el = ref.current;
    if (!el) return;
    const left = Math.abs(el.scrollLeft);
    const max = el.scrollWidth - el.clientWidth;
    const next = { start: left > 1, end: max - left > 1 };
    setEdge((prev) => (prev.start === next.start && prev.end === next.end ? prev : next));
  }, []);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    if (el.firstElementChild) observer.observe(el.firstElementChild);
    return () => observer.disconnect();
  }, [measure]);

  const scrollable = edge.start || edge.end;
  return (
    <div
      ref={ref}
      className={styles.table}
      data-fade-start={edge.start || undefined}
      data-fade-end={edge.end || undefined}
      onScroll={measure}
      // Focusable only when it scrolls, so the keyboard can scroll it.
      tabIndex={scrollable ? 0 : undefined}
      role={scrollable ? "region" : undefined}
      aria-label={scrollable ? "Table" : undefined}
    >
      <table>
        <thead>
          <tr>
            {block.head.map((c, i) => (
              <th key={i} scope="col" data-align={block.align[i] ?? undefined}>
                {inline(c, false)}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {block.rows.map((row, r) => (
            <tr key={r}>
              {row.map((c, i) => (
                <td key={i} data-align={block.align[i] ?? undefined}>
                  {inline(c, false)}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// ---------- Inline ----------

const PUNCTUATION = /[!-/:-@[-`{-~]/;
const SPACE = /\s/;
const WORD = /[\p{L}\p{N}]/u;
const URL = /^https?:\/\/[^\s<]*[^\s<.,:;"'!?)\]*_~]/;
const AUTOLINK = /^<((?:https?:\/\/|mailto:)[^\s<>]+)>/;

const runOf = (text: string, i: number) => {
  let n = 1;
  while (text[i + n] === text[i]) n++;
  return n;
};

/** Where a code span opened at `i` with `n` backticks closes, or -1. */
function codeEnd(text: string, i: number, n: number) {
  for (let j = i + n; j < text.length; j++) {
    if (text[j] !== "`") continue;
    const m = runOf(text, j);
    if (m === n) return j;
    j += m - 1;
  }
  return -1;
}

/** Where `len` delimiters of `ch` close an emphasis opened before `from`, or -1. */
function closer(text: string, from: number, ch: string, len: number) {
  for (let j = from; j < text.length; j++) {
    const c = text[j];
    if (c === "\\") {
      j++;
      continue;
    }
    if (c === "`") {
      const n = runOf(text, j);
      const end = codeEnd(text, j, n);
      j = end < 0 ? j + n - 1 : end + n - 1;
      continue;
    }
    if (c !== ch) continue;
    const n = runOf(text, j);
    const before = text[j - 1];
    const after = text[j + n];
    const closes = j > from && !SPACE.test(before) && (ch !== "_" || after === undefined || !WORD.test(after));
    if (closes) {
      // The closing run's last delimiters close this span; any before them close a nested one.
      if (len === 1 && n !== 2) return j + n - 1;
      if (len === 2 && n >= 2) return j + n - 2;
      if (len === 3 && n >= 3) return j + n - 3;
    }
    j += n - 1;
  }
  return -1;
}

/** Index of the `]` that closes a `[` at `i`, or -1. */
function bracketEnd(text: string, i: number) {
  let depth = 0;
  for (let j = i; j < text.length; j++) {
    const c = text[j];
    if (c === "\\") j++;
    else if (c === "`") {
      const n = runOf(text, j);
      const end = codeEnd(text, j, n);
      j = end < 0 ? j + n - 1 : end + n - 1;
    } else if (c === "[") depth++;
    else if (c === "]" && --depth === 0) return j;
  }
  return -1;
}

/** Index of the `)` that closes a `(` at `i`, or -1. */
function parenEnd(text: string, i: number) {
  let depth = 0;
  for (let j = i; j < text.length; j++) {
    const c = text[j];
    if (c === "\\") j++;
    else if (c === "(") depth++;
    else if (c === ")" && --depth === 0) return j;
    else if (c === "\n") return -1;
  }
  return -1;
}

function Link({ href, children }: { href: string | null; children: ReactNode }) {
  // Unsafe or not yet complete: the words, styled as the link they'll be.
  if (!href) return <span className={styles.link}>{children}</span>;
  const external = /^https?:\/\//i.test(href);
  let host = "";
  if (external) {
    try {
      host = new globalThis.URL(href).host;
    } catch {}
  }
  return (
    <a
      className={styles.link}
      href={href}
      title={host || undefined}
      target={external ? "_blank" : undefined}
      rel={external ? "noopener noreferrer" : undefined}
    >
      {children}
    </a>
  );
}

/**
 * Inline markdown as React nodes: code, strong, emphasis, strikethrough,
 * links and bare URLs. Text is only ever text, so HTML in the source shows
 * as written. With `open` (the end of a streaming reply), an unclosed span
 * runs to the end instead of showing its markers, and a link still being
 * typed shows its words.
 */
export function inline(text: string, open: boolean): ReactNode[] {
  const out: ReactNode[] = [];
  let buf = "";
  let key = 0;
  const flush = () => {
    if (buf) out.push(buf);
    buf = "";
  };
  const push = (node: ReactNode) => {
    flush();
    out.push(node);
  };

  let i = 0;
  while (i < text.length) {
    const c = text[i];
    const rest = text.length - i;

    if (c === "\\" && i + 1 < text.length && PUNCTUATION.test(text[i + 1])) {
      buf += text[i + 1];
      i += 2;
      continue;
    }

    if (c === "\n") {
      push(<br key={key++} />);
      i++;
      continue;
    }

    if (c === "`") {
      const n = runOf(text, i);
      const end = codeEnd(text, i, n);
      if (end >= 0 || open) {
        let code = text.slice(i + n, end >= 0 ? end : undefined).replace(/\n/g, " ");
        if (/^ .*[^ ].* $/.test(code)) code = code.slice(1, -1);
        if (code) push(<code key={key++} className={styles.inlineCode}>{code}</code>);
        i = end >= 0 ? end + n : text.length;
      } else {
        buf += text.slice(i, i + n);
        i += n;
      }
      continue;
    }

    if (c === "*" || c === "_" || c === "~") {
      const n = runOf(text, i);
      const after = text[i + n];
      const before = text[i - 1];
      const opens = after !== undefined && !SPACE.test(after) && (c !== "_" || before === undefined || !WORD.test(before));
      // A marker at the very end of a streaming reply may be about to open a span.
      if (open && after === undefined && (c !== "~" || n <= 2)) {
        i += n;
        continue;
      }
      if (!opens || (c === "~" && n !== 2)) {
        buf += text.slice(i, i + n);
        i += n;
        continue;
      }
      const len = c === "~" ? 2 : Math.min(n, 3);
      const end = closer(text, i + len, c, len);
      if (end < 0 && !open) {
        buf += c;
        i += 1;
        continue;
      }
      const inner = text.slice(i + len, end < 0 ? undefined : end);
      const kids = inline(inner, end < 0 && open);
      const k = key++;
      push(
        c === "~" ? (
          <del key={k}>{kids}</del>
        ) : len === 3 ? (
          <strong key={k}>
            <em>{kids}</em>
          </strong>
        ) : len === 2 ? (
          <strong key={k}>{kids}</strong>
        ) : (
          <em key={k}>{kids}</em>
        ),
      );
      i = end < 0 ? text.length : end + len;
      continue;
    }

    if (c === "[" || (c === "!" && text[i + 1] === "[")) {
      const image = c === "!";
      const s = image ? i + 1 : i;
      const close = bracketEnd(text, s);
      const label = text.slice(s + 1, close < 0 ? undefined : close);
      if (close >= 0 && text[close + 1] === "(") {
        const end = parenEnd(text, close + 1);
        if (end >= 0) {
          const dest = text.slice(close + 2, end).trim().replace(/\s+(["'(]).*$/, "");
          // An image is a link to it, never an <img>: a reply can't make the page fetch a URL.
          push(<Link key={key++} href={safeHref(dest)}>{image ? label || "Image" : inline(label, false)}</Link>);
          i = end + 1;
          continue;
        }
        if (open && !text.slice(close + 1).includes("\n")) {
          push(<Link key={key++} href={null}>{inline(label, false)}</Link>);
          i = text.length;
          continue;
        }
      }
      if (close < 0 && open && !label.includes("\n")) {
        // Still typing the label: show the words so far.
        push(<Fragment key={key++}>{inline(label, true)}</Fragment>);
        i = text.length;
        continue;
      }
      buf += c;
      i++;
      continue;
    }

    if (c === "<") {
      const m = AUTOLINK.exec(text.slice(i));
      if (m) {
        push(<Link key={key++} href={safeHref(m[1])}>{m[1].replace(/^mailto:/, "")}</Link>);
        i += m[0].length;
        continue;
      }
    }

    if (c === "h" && rest > 8 && (i === 0 || !WORD.test(text[i - 1]))) {
      const m = URL.exec(text.slice(i));
      if (m) {
        push(<Link key={key++} href={m[0]}>{m[0]}</Link>);
        i += m[0].length;
        continue;
      }
    }

    buf += c;
    i++;
  }
  flush();
  return out;
}

// A small markdown parser for model replies: CommonMark's common blocks plus
// GitHub's tables, task lists and strikethrough. Blocks only; inline syntax is
// read when rendering. While streaming, the half-typed last line is held back
// when it could still turn into a different block, so raw markers never flash.

export type Align = "left" | "center" | "right" | null;

export type ListItem = { checked: boolean | null; children: Block[] };

export type Block =
  | { type: "paragraph"; text: string }
  | { type: "heading"; depth: number; text: string }
  | { type: "rule" }
  | { type: "code"; language: string; code: string; closed: boolean }
  | { type: "quote"; children: Block[] }
  | { type: "list"; ordered: boolean; start: number; tight: boolean; items: ListItem[] }
  | { type: "table"; align: Align[]; head: string[]; rows: string[][] };

/** A top-level block and the source lines it came from (for memoizing). */
export type Section = { block: Block; source: string };

const FENCE = /^(\s*)(`{3,}|~{3,})(.*)$/;
const HEADING = /^ {0,3}(#{1,6})(?:[ \t]+(.*?))?(?:[ \t]+#+)?[ \t]*$/;
const RULE = /^ {0,3}([-*_])(?:[ \t]*\1){2,}[ \t]*$/;
const QUOTE = /^ {0,3}>/;
const ITEM = /^([ \t]*)([-*+]|\d{1,9}[.)])(?:([ \t]+)(.*)|[ \t]*$)/;
const TABLE_RULE = /^ {0,3}\|?[ \t]*:?-+:?[ \t]*(?:\|[ \t]*:?-+:?[ \t]*)*\|?[ \t]*$/;
const TASK = /^\[([ xX])\](?:[ \t]+|$)/;

// A last line that could still become another block: a heading's #, a list
// marker, a task's box, a quote's >, a fence or rule on its way, any table row.
const UNSETTLED = /^\s*(?:#{1,6}|[-+*]|\d{1,9}[.)]?|>+|`{1,2}|~{1,2}|(?:`{3,}|~{3,}).*|[-*_=]{2,}|(?:[-+*]|\d{1,9}[.)])[ \t]+\[[ xX]?\]?|\|.*)[ \t]*$/;

const blank = (line: string) => !line.trim();
const indentOf = (line: string) => /^[ \t]*/.exec(line)![0].length;

/** Fence opener or closer: its character, length and info string. */
function fence(line: string) {
  const m = FENCE.exec(line);
  if (!m || (m[2][0] === "`" && m[3].includes("`"))) return null;
  return { indent: m[1].length, marker: m[2], info: m[3].trim() };
}

const closes = (line: string, open: string) => {
  const f = fence(line);
  return !!f && f.marker[0] === open[0] && f.marker.length >= open.length && !f.info;
};

/** Is the source inside a code fence at its end? */
function inFence(lines: string[]) {
  let open: string | null = null;
  for (const line of lines) {
    if (open) {
      if (closes(line, open)) open = null;
    } else {
      const f = fence(line);
      if (f) open = f.marker;
    }
  }
  return open !== null;
}

const isTableStart = (lines: string[], i: number) =>
  lines[i].includes("|") && i + 1 < lines.length && lines[i + 1].includes("|") && TABLE_RULE.test(lines[i + 1]);

/** Lines that end a paragraph. */
const interrupts = (lines: string[], i: number) => {
  const line = lines[i];
  return !!fence(line) || HEADING.test(line) || RULE.test(line) || QUOTE.test(line) || isTableStart(lines, i) || (ITEM.test(line) && !!ITEM.exec(line)![4]?.trim());
};

/** Table cells, splitting on pipes that aren't escaped or inside code. */
export function cells(row: string) {
  let s = row.trim();
  if (s.startsWith("|")) s = s.slice(1);
  if (s.endsWith("|") && !s.endsWith("\\|")) s = s.slice(0, -1);
  const out: string[] = [];
  let cell = "";
  let tick = 0;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (ch === "\\" && s[i + 1] === "|") {
      cell += "|";
      i++;
    } else if (ch === "`") {
      let n = 1;
      while (s[i + n] === "`") n++;
      tick = tick === n ? 0 : tick || n;
      cell += s.slice(i, i + n);
      i += n - 1;
    } else if (ch === "|" && !tick) {
      out.push(cell.trim());
      cell = "";
    } else cell += ch;
  }
  out.push(cell.trim());
  return out;
}

function alignOf(cell: string): Align {
  const c = cell.trim();
  const left = c.startsWith(":");
  const right = c.endsWith(":");
  return left && right ? "center" : right ? "right" : left ? "left" : null;
}

type Parsed = { block: Block | null; next: number };

function parseOne(lines: string[], i: number, streaming: boolean): Parsed {
  const line = lines[i];

  const open = fence(line);
  if (open) {
    const body: string[] = [];
    let j = i + 1;
    let closed = false;
    for (; j < lines.length; j++) {
      if (closes(lines[j], open.marker)) {
        closed = true;
        j++;
        break;
      }
      // Body lines lose as much indentation as the opening fence had.
      const strip = Math.min(open.indent, indentOf(lines[j]));
      body.push(lines[j].slice(strip));
    }
    const language = open.info.split(/\s+/)[0] ?? "";
    return { block: { type: "code", language, code: body.join("\n"), closed }, next: j };
  }

  const heading = HEADING.exec(line);
  if (heading) return { block: { type: "heading", depth: heading[1].length, text: heading[2] ?? "" }, next: i + 1 };

  if (RULE.test(line)) return { block: { type: "rule" }, next: i + 1 };

  if (QUOTE.test(line)) {
    const inner: string[] = [];
    let j = i;
    // Quote lines, and lazy lines that continue the quote's paragraph.
    while (j < lines.length) {
      if (QUOTE.test(lines[j])) inner.push(lines[j].replace(/^ {0,3}> ?/, ""));
      else if (!blank(lines[j]) && inner.length && !blank(inner[inner.length - 1]) && !interrupts(lines, j)) inner.push(lines[j]);
      else break;
      j++;
    }
    return { block: { type: "quote", children: parseBlocks(inner, streaming) }, next: j };
  }

  if (ITEM.test(line)) return parseList(lines, i, streaming);

  if (isTableStart(lines, i)) {
    const head = cells(lines[i]);
    const align = cells(lines[i + 1]).map(alignOf);
    const rows: string[][] = [];
    let j = i + 2;
    while (j < lines.length && !blank(lines[j]) && lines[j].includes("|") && !interrupts(lines, j)) {
      // Every row has the header's columns: a short row is padded, a long one cut.
      const row = cells(lines[j]);
      rows.push(head.map((_, c) => row[c] ?? ""));
      j++;
    }
    return { block: { type: "table", align: head.map((_, c) => align[c] ?? null), head, rows }, next: j };
  }

  // Rows of a table whose divider hasn't arrived: hold them back until it does.
  const rest = lines.slice(i, blank(lines[lines.length - 1]) ? -1 : undefined);
  if (streaming && rest.every((l) => l.trim().startsWith("|"))) {
    return { block: null, next: lines.length };
  }

  // A paragraph always takes its first line, so nothing can stall the loop.
  const para = [line.trim()];
  let j = i + 1;
  while (j < lines.length && !blank(lines[j]) && !interrupts(lines, j)) para.push(lines[j++].trim());
  return { block: { type: "paragraph", text: para.join("\n") }, next: j };
}

function parseList(lines: string[], i: number, streaming: boolean): Parsed {
  const first = ITEM.exec(lines[i])!;
  const indent = first[1].length;
  const ordered = /\d/.test(first[2]);
  const start = ordered ? parseInt(first[2], 10) : 1;
  const items: ListItem[] = [];
  let tight = true;

  const sibling = (line: string) => {
    const m = ITEM.exec(line);
    return !!m && !RULE.test(line) && m[1].length <= indent + 1 && /\d/.test(m[2]) === ordered;
  };

  while (i < lines.length && sibling(lines[i])) {
    const m = ITEM.exec(lines[i])!;
    // Where the item's text starts; deeper lines belong to the item.
    const content = m[1].length + m[2].length + Math.min(m[3]?.length ?? 1, 4);
    const body = [m[4] ?? ""];
    i++;
    while (i < lines.length) {
      const line = lines[i];
      if (blank(line)) {
        let j = i;
        while (j < lines.length && blank(lines[j])) j++;
        if (j < lines.length && indentOf(lines[j]) > indent + 1 && !sibling(lines[j])) {
          tight = false;
          for (; i < j; i++) body.push("");
          continue;
        }
        break;
      }
      const ind = indentOf(line);
      if (ind > indent && !sibling(line)) {
        body.push(line.slice(Math.min(ind, content)));
      } else if (!blank(body[body.length - 1]) && !interrupts(lines, i) && !ITEM.test(line)) {
        // A lazy line: it carries on the item's paragraph.
        body.push(line.trim());
      } else break;
      i++;
    }

    const task = TASK.exec(body[0]);
    if (task) body[0] = body[0].slice(task[0].length);
    items.push({ checked: task ? task[1] !== " " : null, children: parseBlocks(body, streaming) });

    // A blank line between items makes the list loose.
    let j = i;
    while (j < lines.length && blank(lines[j])) j++;
    if (j > i && j < lines.length && sibling(lines[j])) {
      tight = false;
      i = j;
    }
  }
  return { block: { type: "list", ordered, start, tight, items }, next: i };
}

function parseBlocks(lines: string[], streaming: boolean): Block[] {
  return parseSections(lines, streaming).map((s) => s.block);
}

function parseSections(lines: string[], streaming: boolean): Section[] {
  const out: Section[] = [];
  let i = 0;
  while (i < lines.length) {
    if (blank(lines[i])) {
      i++;
      continue;
    }
    const { block, next } = parseOne(lines, i, streaming);
    if (block) out.push({ block, source: lines.slice(i, next).join("\n") });
    i = next;
  }
  return out;
}

/** The source as blocks. While `streaming`, a half-typed last line that
 *  could still change what block it is waits for the rest of its line. */
export function parse(source: string, streaming = false): Section[] {
  const lines = source.replace(/\r\n?/g, "\n").replace(/\t/g, "    ").split("\n");
  if (streaming && lines.length) {
    const last = lines[lines.length - 1];
    if (last && UNSETTLED.test(last) && !inFence(lines.slice(0, -1))) lines.pop();
  }
  return parseSections(lines, streaming);
}

// ---------- Links ----------

/** A link's href if it's safe to follow: http(s), mailto, tel or relative. */
export function safeHref(raw: string): string | null {
  const href = raw.trim().replace(/^<|>$/g, "");
  const probe = href.replace(/[\u0000- \u007F]+/g, "").toLowerCase();
  if (/^(https?:|mailto:|tel:)/.test(probe)) return href;
  if (/^[a-z][a-z0-9+.-]*:/.test(probe) || probe.startsWith("//")) return null;
  return href;
}
